-- Series 36SN products (128) + filter values. Run AFTER seed_series_36sn_info.sql.
-- 8 priced (3-Way / Tri-Clamp / Cavity Filler Seat / W Handle); 120 quote-only (Price NULL).
DECLARE @SeriesName nvarchar(100) = N'Series 36SN';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);

INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'Size'),(N'End Connection'),(N'Operating Pressure'),(N'Way'),(N'Seat'),(N'Handle')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);

INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder
FROM (VALUES (N'End Connection',0),(N'Size',1),(N'Way',2),(N'Seat',3),(N'Handle',4),(N'Operating Pressure',5)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName
WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);

